"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["7058"],{3191(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>l,frontMatter:()=>r,contentTitle:()=>a,toc:()=>d,assets:()=>c});var i=JSON.parse('{"id":"SoftwareEngineering/documentation","title":"Documentation","description":"Documentation is what lets knowledge outlive the person who had it in their head. This page covers READMEs, Architecture Decision Records (ADRs), and inline documentation \u2014 what each is for, and how to keep them from going stale.","source":"@site/docs/SoftwareEngineering/21-documentation.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/documentation","permalink":"/Mindstack/docs/SoftwareEngineering/documentation","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":21,"frontMatter":{"title":"Documentation","sidebar_label":"Documentation","sidebar_position":21},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Technical Debt","permalink":"/Mindstack/docs/SoftwareEngineering/technical-debt"},"next":{"title":"Legacy Code","permalink":"/Mindstack/docs/SoftwareEngineering/legacy-code"}}'),o=t(4848),s=t(8453);let r={title:"Documentation",sidebar_label:"Documentation",sidebar_position:21},a="Documentation",c={},d=[{value:"The Documentation Hierarchy",id:"the-documentation-hierarchy",level:2},{value:"Writing a Good README",id:"writing-a-good-readme",level:2},{value:"Architecture Decision Records (ADRs)",id:"architecture-decision-records-adrs",level:2},{value:"Inline Documentation and Docstrings",id:"inline-documentation-and-docstrings",level:2},{value:"Keeping Documentation From Going Stale",id:"keeping-documentation-from-going-stale",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function h(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"documentation",children:"Documentation"})}),"\n",(0,o.jsx)(n.p,{children:"Documentation is what lets knowledge outlive the person who had it in their head. This page covers READMEs, Architecture Decision Records (ADRs), and inline documentation \u2014 what each is for, and how to keep them from going stale."}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"the-documentation-hierarchy",children:"The Documentation Hierarchy"}),"\n",(0,o.jsx)(n.p,{children:"Different kinds of documentation answer different questions, for different audiences, at different points in a project's life. Using the wrong kind for the job \u2014 or writing everything as one giant wiki page \u2014 is a common source of documentation nobody actually reads or trusts."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'README                     \u2192 "What is this, and how do I get started?"\n                            First thing a new engineer or user reads.\n  \nArchitecture Decision      \u2192 "Why did we choose THIS approach, and what\nRecords (ADRs)               else did we consider?"\n                            Historical record of significant decisions.\n  \nInline code comments       \u2192 "Why does this specific, non-obvious piece\n                            of code work this way?"\n                            Right next to the code it explains.\n  \nAPI documentation          \u2192 "What does this function/endpoint do,\n                            what does it take, what does it return?"\n                            Reference material for callers.\n\nRunbooks/operational docs  \u2192 "What do I do when THIS specific thing\n                            goes wrong?"\n                            (Covered in depth in the DevOps course\'s\n                            observability page \u2014 the same document\n                            type, same purpose.)\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"writing-a-good-readme",children:"Writing a Good README"}),"\n",(0,o.jsx)(n.p,{children:"The README is almost always the first thing anyone \u2014 a new team member, an external contributor, your own future self after months away \u2014 reads. It sets the tone for the whole project."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-markdown",children:'# Project Name\n\nOne or two sentences: what does this actually do, and why does it exist?\n\n## Quick Start\n\nThe FASTEST path from "I just cloned this" to "I have it running\nlocally." Every unnecessary step here is friction that loses readers.\n\n    git clone <repo>\n    cd project\n    npm install\n    npm run dev\n\n## Prerequisites\n\n- Node.js 20+\n- PostgreSQL 16+\n- (anything else genuinely required before the Quick Start works)\n\n## Project Structure\n\nA brief orientation \u2014 not exhaustive, just enough for a newcomer to\nknow where to look for what:\n\n    src/\n      handlers/   HTTP request handlers\n      services/   business logic\n      models/     data structures\n\n## Running Tests\n\n    npm test\n\n## Deployment\n\nLink to more detailed deployment docs if this would otherwise make\nthe README too long \u2014 the README\'s job is orientation, not being\nthe single exhaustive source for everything.\n\n## Contributing\n\nLink to a CONTRIBUTING.md if the project has one, or brief inline\nguidance (branch naming, PR process \u2014 see file 19, Code Review) if not.\n'})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"What makes a README GOOD, specifically:\n  A newcomer can get the project running locally within minutes,\n  not hours \u2014 this is the single highest-value thing a README does\n  Assumes minimal prior context \u2014 don't assume the reader already\n  knows internal jargon, acronyms, or \"how we do things here\"\n  Stays SHORT \u2014 link out to deeper documentation rather than trying\n  to be the one exhaustive document; a README that's grown to 2,000\n  lines has usually stopped being read carefully by anyone\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"architecture-decision-records-adrs",children:"Architecture Decision Records (ADRs)"}),"\n",(0,o.jsx)(n.p,{children:"A short document capturing ONE significant architectural decision \u2014 the context that led to it, the decision itself, and the consequences/trade-offs accepted."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-markdown",children:"# ADR-0012: Use PostgreSQL Instead of MongoDB for Order Data\n\n## Status\nAccepted\n\n## Context\nOur order data has clear, stable relationships (orders \u2192 line items \u2192\nproducts, orders \u2192 customer) and we need strong consistency guarantees\nfor inventory reservation during checkout (see file 17, CAP Theorem \u2014\nthis specific data needs strong consistency, even though other parts\nof our system are fine with eventual consistency).\n\nWe initially considered MongoDB for its flexible schema, anticipating\nthat order data structure might change frequently as the product evolves.\n\n## Decision\nWe will use PostgreSQL for all order-related data.\n\n## Consequences\nPositive:\n  - Strong consistency for inventory reservation, avoiding overselling\n  - Mature tooling for migrations, backups, and read replicas\n  - The team already has deep PostgreSQL operational experience\n\nNegative:\n  - Schema changes require migrations (see file 14, Database Design)\n    rather than MongoDB's flexible document structure \u2014 a deliberate\n    trade-off, since order data has proven stable in practice over\n    the exploration we did before this decision\n\n## Alternatives Considered\n  - MongoDB: rejected due to weaker consistency guarantees for the\n    inventory reservation use case specifically\n  - DynamoDB: rejected due to team's limited operational experience\n    with it, and our data's genuinely relational shape\n"})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'Why ADRs matter \u2014 the specific problem they solve:\n\nWithout them: six months later, someone (possibly the same engineer\nwho made the original decision) asks "wait, why did we choose\nPostgreSQL over MongoDB here?" \u2014 and the answer has to be\nreconstructed from memory, old Slack messages, or isn\'t recoverable\nat all. Worse, someone might "fix" this "obviously wrong" decision\nwithout understanding the original, still-valid reasoning behind it.\n\nWith them: the reasoning is preserved permanently, in context, right\nalongside the decision \u2014 anyone questioning the choice later can\nread the original trade-off analysis before deciding whether\ncircumstances have genuinely changed enough to warrant revisiting it.\n\nWhen to write one: for decisions that are genuinely hard to reverse,\naffect multiple people/teams, or where the reasoning itself (not\njust the decision) has lasting value. Not every decision needs an\nADR \u2014 a simple, easily-reversible choice doesn\'t warrant the overhead.\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"inline-documentation-and-docstrings",children:"Inline Documentation and Docstrings"}),"\n",(0,o.jsx)(n.p,{children:"Covered in depth, per-language, in the language courses on this site (see each course's error handling and functions pages) \u2014 the strategic guidance here is what makes inline documentation actually worth maintaining."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-python",children:'def calculate_shipping_cost(weight_kg: float, distance_km: float, is_express: bool) -> float:\n    """\n    Calculate shipping cost based on weight, distance, and speed tier.\n\n    Uses the 2024 carrier rate card (see docs/shipping-rates.md for\n    the full rate table this implements).\n\n    Args:\n        weight_kg: package weight in kilograms, must be positive\n        distance_km: shipping distance in kilometers\n        is_express: whether express (2-day) shipping is requested\n\n    Returns:\n        Shipping cost in USD\n\n    Raises:\n        ValueError: if weight_kg is zero or negative\n    """\n    if weight_kg <= 0:\n        raise ValueError("weight must be positive")\n    base_rate = weight_kg * 0.5 + distance_km * 0.01\n    return base_rate * 1.8 if is_express else base_rate\n'})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Good docstring content \u2014 things the CODE ITSELF cannot express:\n  What the function does, from the CALLER's perspective (not a\n  restatement of the implementation)\n  Parameter constraints not obvious from the type signature alone\n  (weight_kg must be positive \u2014 the type `float` alone doesn't say that)\n  What exceptions can be raised, and under what conditions\n  A link to further context (a spec, a related document) when the\n  function implements something with real external documentation\n\nDocstrings for EVERY function, including trivial private helpers\nwhose purpose is obvious from their name and one-line body, are\nusually not worth the maintenance burden \u2014 reserve them for PUBLIC\nAPIs (functions other code/other teams will call without reading the\nimplementation) and anything with genuinely non-obvious behavior.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"keeping-documentation-from-going-stale",children:"Keeping Documentation From Going Stale"}),"\n",(0,o.jsx)(n.p,{children:"Stale documentation is often worse than no documentation \u2014 it actively misleads readers who reasonably trust it, and rebuilding trust in a team's documentation after it's been found wrong repeatedly is hard."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Practical strategies:\n\nPut documentation NEXT TO the code it describes, in the same repo,\n  reviewed in the same PRs \u2014 a README or docstring change that's\n  part of the same PR as the code change it describes is far more\n  likely to stay in sync than a wiki page living in a completely\n  separate system, edited (or not) independently.\n\nPrefer documentation that's HARD to let go stale:\n  A docstring with an executable example (like Go's Example\n  functions, covered in the Go course's testing page, or doctest\n  in Python) is VERIFIED by the test suite \u2014 it literally cannot\n  silently go stale without a test failing to alert you.\n  Generated API documentation (from OpenAPI specs, from code\n  annotations) stays in sync automatically because it's derived\n  FROM the code, not maintained as a separate parallel document.\n\nDelete documentation you know is stale rather than leaving it \u2014\n  wrong documentation actively misleads; no documentation at least\n  doesn't actively lie to the reader.\n\nPeriodically review high-traffic docs (the README, key ADRs, onboarding\n  guides) as part of a recurring team practice \u2014 not necessarily every\n  sprint, but at some deliberate cadence, rather than never.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:'Match the documentation type to the actual question being answered \u2014 a README for "how do I get started," an ADR for "why did we choose this," inline comments for "why does this specific weird code exist."'}),"\n",(0,o.jsx)(n.li,{children:"Keep READMEs short and link out to deeper docs \u2014 a README's job is fast orientation, not being the exhaustive source of truth for everything."}),"\n",(0,o.jsx)(n.li,{children:"Write an ADR for decisions that are hard to reverse or where the reasoning has lasting value \u2014 not every decision needs one, but the genuinely significant ones are worth the ten minutes it takes."}),"\n",(0,o.jsx)(n.li,{children:"Prefer documentation that's structurally hard to let go stale (executable examples, generated API docs) over documentation that relies purely on someone remembering to update it manually."}),"\n",(0,o.jsx)(n.li,{children:"Delete documentation you know is wrong rather than leaving it \u2014 stale docs that actively mislead are a worse outcome than the same information simply not existing yet."}),"\n"]}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"Different documentation types answer different questions: README (getting started), ADRs (why a decision was made), inline docs (why specific code works the way it does), API docs (reference for callers)."}),"\n",(0,o.jsx)(n.li,{children:"A good README gets a newcomer running the project in minutes, assumes minimal prior context, and stays short by linking to deeper documentation rather than trying to cover everything itself."}),"\n",(0,o.jsx)(n.li,{children:"ADRs capture the context, decision, and consequences of significant, hard-to-reverse architectural choices \u2014 preserving the reasoning, not just the outcome, for anyone questioning it later."}),"\n",(0,o.jsx)(n.li,{children:"Inline documentation (docstrings/comments) is most valuable on public APIs and genuinely non-obvious code \u2014 not every trivial function needs one."}),"\n",(0,o.jsx)(n.li,{children:"Keep documentation from going stale by co-locating it with the code it describes (reviewed in the same PRs), preferring structurally-verified formats (executable examples, generated docs), and deleting documentation known to be wrong rather than leaving it to mislead readers."}),"\n"]})]})}function l(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>a});var i=t(6540);let o={},s=i.createContext(o);function r(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);